export const keywordPageByPath=Object.fromEntries(keywordPages.map(page=>[page.path,page]));
export const keywordGroups={nasional:'Website nasional','jenis-website':'Jenis website',industri:'Jenis usaha',lokasi:'Kota & daerah',fitur:'Fitur website'};
const services=['landing page','company profile','toko online','website e-commerce','portofolio','personal branding','aplikasi web','sistem booking','katalog produk','website ekspor','portal artikel','website multibahasa'];
const serviceFoci=['satu pesan dan satu tindakan pengunjung','profil perusahaan dan layanan yang mudah dinilai','produk, varian, serta alur pemesanan yang rapi','alur belanja dan informasi transaksi','galeri karya dan kontak proyek','keahlian, pengalaman, serta formulir kolaborasi','pengelolaan data dan proses operasional','jadwal, ketersediaan, dan konfirmasi reservasi','kategori, detail barang, dan permintaan harga','katalog B2B serta komunikasi buyer','kualitas artikel dan susunan rubrik','informasi yang konsisten dalam beberapa bahasa'];
const industries=['coffee shop','restoran','toko baju','brand skincare','klinik kecantikan','salon','biro travel','rental mobil','villa','penginapan','sekolah','lembaga kursus','agen properti','kontraktor','supplier industri','toko elektronik','perusahaan ekspor','katering','studio arsitek','konsultan bisnis'];
const industryFoci=['menu dan cara pemesanan','menu, lokasi layanan, dan reservasi','koleksi, ukuran, dan warna','katalog produk serta keterangan perawatan yang benar','informasi layanan tanpa klaim hasil berlebihan','harga layanan dan jadwal','paket, fasilitas, dan tanggal kegiatan','daftar armada serta syarat sewa','fasilitas, kapasitas, dan inquiry jadwal','pilihan kamar, aturan, dan reservasi','program sekolah serta pengumuman resmi','materi kursus, jadwal, dan pendaftaran','listing yang statusnya selalu diperbarui','layanan serta dokumentasi proyek berizin','spesifikasi dan penawaran jumlah besar','spesifikasi produk dan informasi garansi','produk dan dokumen ekspor yang valid','paket porsi dan pesanan acara','portofolio karya yang mendapat izin','kompetensi dan pengajuan proposal'];
const features=['form konsultasi','tombol WhatsApp','katalog produk','varian produk','keranjang belanja','checkout','payment gateway','dashboard admin','manajemen stok','booking online','kalender reservasi','CMS artikel','multibahasa','login pelanggan','optimasi SEO','tampilan mobile','galeri portofolio','tabel harga','integrasi email','form permintaan penawaran'];
const featureFoci=['form singkat dengan izin pengumpulan data','jalur kontak resmi dengan konteks pesan','kategori dan detail produk','pilihan ukuran, warna, dan stok','ringkasan pesanan yang tepat','detail biaya dan data pembeli','proses pembayaran setelah aktivasi akun gateway','hak akses, pencatatan perubahan, serta alur pengelolaan','stok yang konsisten dengan pesanan','permintaan jadwal dan validasi ketersediaan','pengelolaan kalender yang mencegah bentrok','draf, peninjauan, dan publikasi konten','teks terjemahan yang benar-benar lengkap','perlindungan akun dan privasi data','struktur judul, metadata, dan internal link','navigasi yang nyaman di ponsel','gambar berkualitas yang tetap cepat dibuka','rincian paket dan komponen biaya','pengiriman email hanya sesuai izin','informasi spesifikasi bagi tim penjualan'];
const placeNames=keywordPages.filter(page=>page.cluster==='lokasi'&&(page.id-345)%3===0).map(page=>page.keyword.replace(/^jasa bikin website /,''));
const formats=['Kebutuhan utama','Alternatif pendekatan','Komponen biaya','Paket dan ruang lingkup','Perbandingan vendor','Konsultasi awal','Arah desain','Tahapan pengembangan','Kebutuhan lanjutan','Langkah memulai','Contoh penerapan','Evaluasi hasil'];
export function keywordBrief(page){
 const price=page.intent.includes('price'),index=page.id;
 let subject='bisnis',focus='tampilan website yang jelas dan mudah digunakan',angle='Rencana website profesional',audience='calon pelanggan';
 if(page.cluster==='jenis-website'){const p=Math.floor((index-41)/12);subject=services[p];focus=serviceFoci[p];angle=formats[(index-41)%12];audience='pengunjung '+subject}
 if(page.cluster==='industri'){const p=Math.floor((index-185)/8);subject=industries[p];focus=industryFoci[p];angle=['Kebutuhan bisnis','Pemetaan fitur','Tampilan dan konten','Biaya pengembangan','Ide desain','Alur informasi','Prioritas fitur','Jalur inquiry'][(index-185)%8];audience='pelanggan '+subject}
 if(page.cluster==='lokasi'){const p=Math.floor((index-345)/3);subject=placeNames[p];focus='profil usaha, halaman layanan, dan cara menghubungi penyedia jasa';angle=['Pengenalan kebutuhan','Alur pembuatan','Pertimbangan biaya'][(index-345)%3];audience='pemilik bisnis di '+subject}
 if(page.cluster==='fitur'){const p=Math.floor((index-561)/2);subject=features[p];focus=featureFoci[p];angle=price?'Perkiraan biaya fitur':'Perancangan fungsi';audience='pengunjung dan pengelola'}
 if(page.cluster==='nasional'){angle=price?'Estimasi dan paket website':'Fondasi bisnis online';subject='website profesional';audience='pelanggan bisnis'}
 const intro=page.cluster==='lokasi'?
 'Untuk pemilik usaha di '+subject+', pembuatan website bisa direncanakan melalui konsultasi online. Halaman ini tidak menyatakan bahwa BisaBikinWeb memiliki kantor atau proyek yang sudah selesai di wilayah tersebut.':
 page.cluster==='industri'?'Bisnis '+subject+' membutuhkan informasi yang membantu pelanggan memahami '+focus+'. Rancangan website sebaiknya menyesuaikan kegiatan operasional sebenarnya.':
 page.cluster==='fitur'?'Implementasi '+subject+' perlu merancang '+focus+'. Biaya dan durasi bergantung sistem yang sudah dipakai serta integrasi yang diperlukan.':
 page.cluster==='jenis-website'?'Kebutuhan '+subject+' sebaiknya berfokus pada '+focus+'. Fitur lain dapat ditambahkan apabila benar-benar membantu tujuan pengunjung.':
 'Website profesional harus membantu '+audience+' menemukan informasi dan menghubungi bisnis. Tentukan layanan, tujuan, dan materi sejak awal sebelum memutuskan desain.';
 const steps=price?
 ['Tentukan fitur yang wajib dimiliki sebelum membandingkan paket.','Periksa biaya domain, hosting, dan layanan pihak ketiga.','Minta rincian desain, revisi, pengujian, dan serah terima.','Nilai biaya pemeliharaan sekaligus manfaat untuk bisnis.']:
 ['Tentukan siapa pengguna utama dan tindakan yang diinginkan.','Kumpulkan materi yang valid: layanan, produk, gambar, dan kontak.','Rancang halaman yang menonjolkan '+focus+'.','Uji pengalaman seluler dan alur konsultasi sebelum publikasi.'];
 const questions=[
  ['Apa prioritas awal untuk kebutuhan ini?','Mulai dari tujuan bisnis, materi yang siap dipublikasikan, dan fungsi utama website. Hindari menambah fitur yang belum diperlukan.'],
  ['Bagaimana memperkirakan biayanya?','Biaya ditentukan oleh jenis website, jumlah halaman, integrasi, desain, serta kebutuhan pemeliharaan. Harga final mengikuti proposal yang disepakati.'],
  ['Apakah bisa dikerjakan dari luar Yogyakarta?','Bisa. Brief, desain, revisi, dan serah terima dapat dilakukan secara online tanpa pertemuan tatap muka.']
 ];
 return {subject,focus,angle,audience,intro,steps,questions,price};
}
